contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public payable {
        require(true);

        bool initializedReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initializedReverted = true;
        } else {
            initializedReverted = false;
        }

        require(!initializedReverted);

        bool setMinSumReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        assert(initializedReverted == false && setMinSumReverted == true);
    }

    receive() external payable {}
}

