// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val) internal {
        vm.assume(true);
        bool initializedReverted;
        try c.Initialized() {
            initializedReverted = false;
        } catch {
            initializedReverted = true;
        }
        vm.assume(!initializedReverted);
        bool setMinSumReverted;
        try c.SetMinSum(val) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }
        assertTrue(initializedReverted == false && setMinSumReverted == true);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
